#!/bin/sh
# generate-formula.sh <tag> <checksums-file>
#
# Emits the Homebrew formula for a wt release to stdout: a binary formula
# whose per-platform URLs point at the GitHub release tarballs, with sha256s
# taken from the release's checksums.txt. The release workflow uses this to
# bump tito0224/homebrew-tap on every tag.
set -eu

TAG="$1"
SUMS="$2"
VERSION="${TAG#v}"
REPO="tito0224/wt"

sha() {
	grep "wt_${TAG}_$1.tar.gz" "$SUMS" | awk '{print $1}'
}

cat <<EOF
# Generated by scripts/generate-formula.sh for ${TAG}. Do not edit by hand.
class Wt < Formula
  desc "Git worktree manager with an interactive, PR-aware TUI"
  homepage "https://github.com/${REPO}"
  version "${VERSION}"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/${REPO}/releases/download/${TAG}/wt_${TAG}_darwin_arm64.tar.gz"
      sha256 "$(sha darwin_arm64)"
    end
    on_intel do
      url "https://github.com/${REPO}/releases/download/${TAG}/wt_${TAG}_darwin_amd64.tar.gz"
      sha256 "$(sha darwin_amd64)"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/${REPO}/releases/download/${TAG}/wt_${TAG}_linux_arm64.tar.gz"
      sha256 "$(sha linux_arm64)"
    end
    on_intel do
      url "https://github.com/${REPO}/releases/download/${TAG}/wt_${TAG}_linux_amd64.tar.gz"
      sha256 "$(sha linux_amd64)"
    end
  end

  def install
    bin.install "wt"
  end

  def caveats
    <<~EOS
      To enable cd-in-place shell integration, run:
        wt shell install
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/wt --version")
  end
end
EOF
